# function_implementation_file
from typing import List, Dict, Any, Optional, Callable
from dataclasses import dataclass, field


@dataclass
class SearchResult:
    id: str
    score: float
    text: str
    metadata: dict[str, Any] = field(default_factory=dict)


def aggregate_search_results(
    search_results: List[SearchResult],
    group_by_field: str,
    aggregation_funcs: Optional[Dict[str, Callable]] = None
) -> Dict[str, Dict[str, Any]]:
    """Aggregate search results by a metadata field with optional statistics.

    Args:
        search_results: List of SearchResult objects to aggregate
        group_by_field: Metadata field name to group by
        aggregation_funcs: Optional dictionary mapping field_name to aggregation function.
            Example: {"score": max, "count": len}
            If None, defaults to count and average score per group

    Returns:
        Dictionary mapping group_value to aggregated statistics
        Example: {"tech": {"count": 5, "avg_score": 0.85, "max_score": 0.95}}
    """
    # Group results by the specified metadata field
    groups: Dict[str, List[SearchResult]] = {}

    for result in search_results:
        # Get the group value from metadata, defaulting to 'unknown' if missing
        group_value = result.metadata.get(group_by_field, 'unknown')

        # Convert group_value to string for consistent key handling
        group_key = str(group_value)

        if group_key not in groups:
            groups[group_key] = []
        groups[group_key].append(result)

    # Calculate aggregated statistics for each group
    aggregated_stats: Dict[str, Dict[str, Any]] = {}

    for group_key, group_results in groups.items():
        if aggregation_funcs is None:
            # Default aggregation: count, avg_score, max_score, min_score
            scores = [r.score for r in group_results]
            aggregated_stats[group_key] = {
                "count": len(group_results),
                "avg_score": sum(scores) / len(scores) if scores else 0.0,
                "max_score": max(scores) if scores else 0.0,
                "min_score": min(scores) if scores else 0.0
            }
        else:
            # Custom aggregation functions
            stats = {}
            for field_name, agg_func in aggregation_funcs.items():
                if field_name == "count":
                    stats[field_name] = agg_func(group_results)
                elif field_name == "score":
                    scores = [r.score for r in group_results]
                    stats[field_name] = agg_func(scores) if scores else 0.0
                else:
                    # For other fields, try to extract from metadata or result attributes
                    try:
                        values = [getattr(r, field_name, r.metadata.get(field_name)) 
                                 for r in group_results]
                        values = [v for v in values if v is not None]
                        if values:
                            stats[field_name] = agg_func(values)
                    except Exception:
                        pass

            aggregated_stats[group_key] = stats

    return aggregated_stats
```

