        index_file = source.get("index_path", "")

        # Resolve paths relative to metadata file directory
        meta_dir = Path(meta_path_str).parent

        if not Path(passage_file).is_absolute():
            passage_file = str(meta_dir / passage_file)
        if not Path(index_file).is_absolute():
            index_file = str(meta_dir / index_file)

        # Check if index file exists
        if not Path(index_file).exists():
            raise FileNotFoundError(f"Passage index file not found: {index_file}")

